    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    medium_supply = supply <= 20

    if hp <= 2 or no_water_days >= 2:
        base = 92.0 if tight_supply else 78.0
        if desperate_pressure >= 2:
            base += 8.0
        return max(0.0, min(budget, base))

    if hp <= 4 or no_water_days >= 1:
        if high_prev >= 110:
            base = 18.0 if not tight_supply else 32.0
        elif high_prev >= 80:
            base = 36.0 if not tight_supply else 48.0
        else:
            base = 44.0 if medium_supply else 38.0
        if desperate_pressure >= 2:
            base += 10.0
        return max(0.0, min(budget, base))

    if high_prev >= 110:
        base = 6.0 if supply >= 20 else 10.0
    elif avg_prev >= 70:
        base = 12.0 if supply >= 20 else 18.0
    else:
        base = 24.0 if tight_supply else 16.0

    if rich_pressure >= 2 and high_prev >= 100:
        base = min(base, 10.0 if supply >= 20 else 14.0)

    if day >= 8 and hp >= 6 and no_water_days == 0:
        base = min(base, 8.0 if supply >= 20 else 12.0)

    return max(0.0, min(budget, base))

