def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # Alive opponents and yesterday bid signals
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # If no opponents, take what we can
    if not alive_opps:
        return float(min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    # Extract yesterday bids from immediate previous_trace
    prev_bids = []
    high_prev = []
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is None:
            continue
        try:
            bval = float(b)
        except Exception:
            continue
        prev_bids.append(bval)
        if bval >= 0.75 * DAILY_SALARY:
            high_prev.append(bval)

    # Determine aggressiveness based on whether any opponent was willing to spend heavily
    any_high = len(high_prev) > 0
    max_prev_bid = max(prev_bids) if prev_bids else 0.0

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Baseline bid strategy
    # - If supply is tight (near 15), we need to secure water: bid higher.
    # - If supply is ample (near 25), bid more conservatively.
    supply_tight = supply <= 17.0
    supply_mid = (supply > 17.0) and (supply <= 21.0)

    # If we are in danger, increase bid.
    danger = (hp <= 2.5) or (no_water_days >= 2)

    # Target bid computation
    if danger:
        # Spend to avoid death; cap by budget
        target = 0.85 * DAILY_SALARY if supply_tight else 0.65 * DAILY_SALARY
    else:
        if any_high:
            # Opponents previously bid aggressively; match enough to beat them when supply is tight.
            # Use a slight undercut vs their max to reduce overspend risk.
            if supply_tight:
                target = min(0.95 * DAILY_SALARY, max_prev_bid * 0.95 + 5.0)
            elif supply_mid:
                target = min(0.75 * DAILY_SALARY, max_prev_bid * 0.85 + 3.0)
            else:
                target = min(0.6 * DAILY_SALARY, max_prev_bid * 0.75 + 2.0)
        else:
            # If nobody bid heavily yesterday, we can bid moderately.
            if supply_tight:
                target = 0.55 * DAILY_SALARY
            elif supply_mid:
                target = 0.45 * DAILY_SALARY
            else:
                target = 0.35 * DAILY_SALARY

    # Ensure we don't bid more than budget; also avoid negative
    if budget <= 0.0:
        return 0.0

    bid = float(min(budget, max(0.0, target)))

    # Additional small adjustment: if supply is extremely low (15), bid slightly higher.
    if supply <= 15.5:
        bid = min(budget, bid + 10.0)

    return float(bid)
